'use strict';

// MODULES //

import DATA from './data.json';


// MAIN //

/**
* Returns a list of SGD penalties.
*
* @returns {Array<string>} list of penalties
*
* @example
* var list = penalties();
* // e.g., returns [ 'elasticnet', 'l1', 'l2', 'none' ]
*/
function penalties() {
	return DATA.slice();
}


// EXPORTS //

export default penalties;
